  quiz: {
    id: "mosp-m3-quiz",
    title: "Module 3 Quiz",
    passPct: 70,
    questions: [
      { id: "q1", question: "A table runs over four pages. How do you make its column titles appear at the top of each page?", options: ["Copy the first row at the top of each page", "Insert a page break before each page", "Table Layout › Data › Repeat Header Rows", "Table Design › Header Row"], answer: 2, explain: "Repeat Header Rows follows the page breaks automatically. The Header Row option only changes formatting." },
      { id: "q2", question: "In a mail merge, what is the Excel list of recipients called?", options: ["The data source", "The main document", "The template", "The merged result"], answer: 0, explain: "The data source holds one row per recipient. The main document holds the text that is the same for everyone." },
      { id: "q3", question: "What does Ctrl + Shift + E do in Word?", options: ["Centres the paragraph", "Inserts a comment", "Opens the Editor pane", "Turns Track Changes on or off"], answer: 3, explain: "Ctrl + Shift + E switches tracking on or off. Ctrl + Alt + M inserts a comment and F7 opens the Editor." },
      { id: "q4", question: "Which Display for Review option shows the edited text with only a red line in the margin where changes were made?", options: ["All Markup", "Simple Markup", "No Markup", "Original"], answer: 1, explain: "Simple Markup is comfortable for reading. Switch to All Markup to see each change in detail." },
      { id: "q5", question: "You renamed several headings. What must you do so the table of contents shows the new names?", options: ["Update page numbers only", "Press Ctrl + S", "References › Update Table › Update entire table", "Insert a new table of contents below the old one"], answer: 2, explain: "Update page numbers only keeps the old text. Update entire table rebuilds the list from the current headings." },
      { id: "q6", question: "Which file type should you use for a company letterhead that everyone reuses?", options: [".dotx", ".docx", ".pdf", ".xlsx"], answer: 0, explain: "A .dotx template opens as a new untitled document each time, so the original letterhead is never overwritten." },
      { id: "q7", question: "You changed a number in a Word table, but the =SUM(ABOVE) total did not change. What do you do?", options: ["Retype the total", "Save the document", "Convert the table to text", "Select the total and press F9"], answer: 3, explain: "Word formulas are fields that do not recalculate by themselves. F9 updates the selected fields." },
      { id: "q8", question: "Which recipient list will work best for a mail merge?", options: ["A list with a merged title in row 1 and totals at the bottom", "One header row in row 1, one row per person, no merged cells and no totals", "A Word table with one person per paragraph", "A list with names and addresses in one column"], answer: 1, explain: "Word reads the first row as field names and creates one letter per row, so the list must be clean and rectangular." },
    ],
  },
